import { existsSync, readFileSync, rmSync, rmdirSync } from 'node:fs'
import { InstallError, type InstallEnv, type Installer } from '../types.ts'
import { REAL_HOME_SKIPPED, isRealHomeInTest, tildePath, writeFileAtomic } from './common.ts'
import { OWNED_MARKER } from './sources/post.ts'

/** A file whose whole content is generated by Quirky. */
export type OwnedFile = { path: string; content: string }

export type OwnedState = 'missing' | 'current' | 'stale' | 'foreign'

/** `foreign` is a file at the path that Quirky didn't write; it is never overwritten or removed. */
export function ownedState(file: OwnedFile): OwnedState {
  if (!existsSync(file.path)) return 'missing'
  let text: string
  try {
    text = readFileSync(file.path, 'utf8')
  } catch {
    return 'foreign'
  }
  if (!text.includes(OWNED_MARKER)) return 'foreign'
  return text === file.content ? 'current' : 'stale'
}

/** Throws InstallError, before anything is written, when a file is one the user wrote. */
export function assertNoForeign(files: OwnedFile[], home: string): void {
  for (const file of files) {
    if (ownedState(file) === 'foreign') throw new InstallError(`${tildePath(file.path, home)} exists and was not written by Quirky`)
  }
}

/** Writes the files whose content differs and returns their paths. */
export function writeOwned(files: OwnedFile[]): string[] {
  const changed: string[] = []
  for (const file of files) {
    if (ownedState(file) === 'current') continue
    writeFileAtomic(file.path, file.content)
    changed.push(file.path)
  }
  return changed
}

/** Deletes the files Quirky wrote, and the directory they were in when that leaves it empty. */
export function removeOwned(files: OwnedFile[], removeDirs: string[] = []): string[] {
  const changed: string[] = []
  for (const file of files) {
    const state = ownedState(file)
    if (state !== 'current' && state !== 'stale') continue
    rmSync(file.path, { force: true })
    changed.push(file.path)
  }
  for (const dir of removeDirs) {
    try {
      rmdirSync(dir)
    } catch {}
  }
  return changed
}

/** Status of a set of owned files: installed only when every one is current. */
export function ownedStatus(files: OwnedFile[], home: string): 'installed' | 'not-installed' | { error: string } {
  const states = files.map((file) => ownedState(file))
  const foreign = files.findIndex((_, index) => states[index] === 'foreign')
  if (foreign !== -1) return { error: `${tildePath(files[foreign]!.path, home)} exists and was not written by Quirky` }
  return states.every((state) => state === 'current') ? 'installed' : 'not-installed'
}

/** An agent whose hook is one generated plugin file. */
export function ownedFileInstaller(options: {
  agent: string
  source?: string
  file: (target: InstallEnv) => OwnedFile
}): Installer {
  const { agent, file } = options
  return {
    agent,
    source: options.source ?? agent,
    files: (target) => [file(target).path],
    install(target) {
      if (isRealHomeInTest(target.home)) return { changed: [], message: REAL_HOME_SKIPPED }
      const owned = [file(target)]
      assertNoForeign(owned, target.home)
      return { changed: writeOwned(owned) }
    },
    remove(target) {
      if (isRealHomeInTest(target.home)) return { changed: [], message: REAL_HOME_SKIPPED }
      return { changed: removeOwned([file(target)]) }
    },
    status: (target) => ownedStatus([file(target)], target.home)
  }
}
